startOrbits=function(){cancelAnimationFrame(orbitFrameId);const container=$('.orbit-system');if(!container)return;container.querySelectorAll('.orbit').forEach(x=>x.remove());const track=document.createElement('div');track.className='orbit-track';container.prepend(track);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let last=performance.now();function frame(now){if(!container.isConnected)return;const dt=Math.min(60,now-last);last=now;if(!orbitDrag&&now>orbitRelease){orbitTurn*=Math.exp(-dt/650);orbitTilt*=Math.exp(-dt/650)}const rot=-.42+orbitTurn,ry=145*Math.max(.24,Math.cos(orbitTilt)),rx=250;track.style.cssText=`width:${rx*2}px;height:${ry*2}px;left:${307.5-rx}px;top:${242.5-ry}px;transform:rotate(${rot}rad)`;const others=PLANETS.filter(p=>p.id!==centerPlanet);PLANETS.forEach(p=>{const el=container.querySelector(`[data-planet=${p.id}]`),central=p.id===centerPlanet,i=others.indexOf(p),a=(reduced?0:now/1000)*.09+i*Math.PI*2/5,x=Math.cos(a)*rx,y=Math.sin(a)*ry;const target={x:central?307.5:307.5+x*Math.cos(rot)-y*Math.sin(rot),y:central?242.5:242.5+x*Math.sin(rot)+y*Math.cos(rot),size:central?275:p.size};const pos=orbitPositions[p.id]??={...target};pos.x=target.x;pos.y=target.y;pos.size+=(target.size-pos.size)*(reduced?1:1-Math.exp(-dt/120));el.style.width=pos.size+'px';el.style.height=pos.size+'px';el.style.transform=`translate(${pos.x-pos.size/2}px,${pos.y-pos.size/2}px)`;el.style.zIndex=central?'4':Math.sin(a)>0?'6':'2';el.classList.toggle('is-center',central);el.setAttribute('aria-pressed',String(central));el.setAttribute('aria-label',`${p.name}${central?'，当前中心':'，设为中心'}`);if(central)el.querySelector('.planet-surface').style.transform=`rotate(${orbitTurn}rad)`});if(!reduced||orbitDrag||Math.abs(orbitTurn)>.001||Math.abs(orbitTilt)>.001)orbitFrameId=requestAnimationFrame(frame)}orbitRefresh=()=>{cancelAnimationFrame(orbitFrameId);frame(performance.now())};orbitRefresh()};
