function groupIconPicker(d,attr){if(!d||d.querySelector('.icon-library-tabs'))return;const grid=d.querySelector('.entity-icon-grid');if(!grid)return;const selected=grid.querySelector('[aria-pressed=true]')?.dataset.pickIcon;let category=Object.keys(ICON_GROUPS).find(k=>ICON_GROUPS[k].includes(selected))||Object.keys(ICON_GROUPS)[0];const tabs=document.createElement('div');tabs.className='icon-library-tabs';grid.before(tabs);function paint(){tabs.innerHTML=Object.keys(ICON_GROUPS).map(k=>`<button type="button" data-icon-category="${k}" aria-pressed="${category===k}">${k}</button>`).join('');grid.innerHTML=ICON_GROUPS[category].map(id=>`<button type="button" ${attr}="${id}" aria-label="${ENTITY_ICONS[id][0]}" title="${ENTITY_ICONS[id][0]}" aria-pressed="${selected===id}">${entityIcon(id)}<small>${ENTITY_ICONS[id][0]}</small></button>`).join('')}tabs.onclick=e=>{const b=e.target.closest('[data-icon-category]');if(b){e.stopPropagation();category=b.dataset.iconCategory;paint()}};paint()}
