const pickerBeforeHorizontal=groupIconPicker;groupIconPicker=function(d,attr){pickerBeforeHorizontal(d,attr);const tabs=d?.querySelector('.icon-library-tabs');if(!tabs||tabs.dataset.horizontal)return;tabs.dataset.horizontal='true';tabs.addEventListener('wheel',e=>{if(tabs.scrollWidth<=tabs.clientWidth)return;e.preventDefault();tabs.scrollLeft+=Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY},{passive:false});tabs.addEventListener('click',e=>{const button=e.target.closest('[data-icon-category]');if(!button)return;requestAnimationFrame(()=>{const selected=tabs.querySelector('[aria-pressed=true]');if(selected)tabs.scrollTo({left:selected.offsetLeft-tabs.offsetLeft-(tabs.clientWidth-selected.offsetWidth)/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})})});};
