function paginateBookmarks(){if(view!=='space')return;const g=currentGroup(),section=$('.group:not([hidden])'),cards=section?.querySelector('.cards');if(!cards)return;if(lastPageFilter!==filter){bookmarkPages={};lastPageFilter=filter}const items=[...cards.querySelectorAll(':scope>.bookmark')],size=Number(prefs.bookmarksPerPage)||100,pages=Math.max(1,Math.ceil(items.length/size)),page=Math.max(1,Math.min(bookmarkPages[g.id]||1,pages));bookmarkPages[g.id]=page;items.forEach((el,i)=>el.classList.toggle('page-hidden',i<(page-1)*size||i>=page*size));$('#bookmark-pagination')?.remove();section.insertAdjacentHTML('beforeend',`<nav id="bookmark-pagination" aria-label="网址分页"><span>共 ${items.length} 条</span><label>每页 <select id="bookmark-page-size" aria-label="每页数量">${[10,20,50,80,100,200].map(n=>`<option ${size===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="page-navigation"><button data-bookmark-page="1" ${page===1?'disabled':''} aria-label="首页">«</button><button data-bookmark-page="${page-1}" ${page===1?'disabled':''} aria-label="上一页">‹</button><label><input id="bookmark-page-jump" type="text" inputmode="numeric" aria-label="跳转页码" value="${page}"><span> / ${pages}</span></label><button data-bookmark-page="${page+1}" ${page===pages?'disabled':''} aria-label="下一页">›</button><button data-bookmark-page="${pages}" ${page===pages?'disabled':''} aria-label="尾页">»</button></div></nav>`);$('#bookmark-page-size').onchange=e=>{prefs.bookmarksPerPage=Number(e.target.value);bookmarkPages[g.id]=1;persist();paginateBookmarks()};const jump=$('#bookmark-page-jump');jump.onchange=()=>{bookmarkPages[g.id]=Math.max(1,Math.min(pages,parseInt(jump.value)||1));paginateBookmarks();$('.group-tab-bar').scrollIntoView({block:'start',behavior:'smooth'})};jump.onkeydown=e=>{if(e.key==='Enter')jump.blur()};enhanceControls()}
