// Membership introductions share one dialog; the entry selects the relevant category.
let memberGateContext={};
// Popup summaries use the best published allowance; detailed package comparison stays in the member center.
function gateBestBenefit(kind,read){
 const plans=memberCatalogPlans(kind);
 if(!window.__shiyuMemberCatalog?.ready)return {text:'正在读取权益',differs:false};
 if(!plans.length)return {text:'暂未开放',differs:false};
 const values=plans.map(read),best=values.reduce((a,b)=>b.rank>a.rank?b:a);
 return {text:best.text,differs:new Set(values.map(v=>v.text)).size>1};
}
function gateQuantity(key,kind){return gateBestBenefit(kind,plan=>{
 const b=plan.entitlements?.find(item=>item.key===key);
 if(!b?.enabled||b.kind!=='quantity')return {rank:-1,text:'暂未开放'};
 if(b.unlimited)return {rank:Infinity,text:'不限量'};
 const value=Number(b.value);return b.value!==''&&Number.isFinite(value)&&value>=0?{rank:value,text:value+' '+(b.unit||'个')}:{rank:-1,text:'暂未开放'};
})}
function gateSelection(key,kind,label){return gateBestBenefit(kind,plan=>{
 if(!window.__shiyuMemberResources)return {rank:0,text:'正在读取权益'};
 const b=plan.entitlements?.find(item=>item.key===key),selected=b?.enabled&&Array.isArray(b.value)?b.value.map(String):[];
 const options=window.ShiyuEntitlements?.options(key).filter(item=>item.enabled!==false)||[];
 let count=options.filter(item=>selected.includes(String(item.id))).length;
 if(key==='global-colors'&&plan.entitlements?.some(item=>item.key==='global-custom-color'&&item.enabled))count++;
 return {rank:count,text:count+' 种'+label};
})}
function gateFlags(kind,definitions,base=''){return gateBestBenefit(kind,plan=>{
 const names=definitions.filter(([key])=>plan.entitlements?.some(b=>b.key===key&&b.enabled)).map(([,name])=>name);
 return {rank:names.length,text:[base,...names].filter(Boolean).join('、')||'暂未开放'};
})}
function gateComparison(read){return ['free','paid'].map(kind=>{
 const segments=read(kind),text=segments.map(s=>s.text).join(' · ');
 return (kind==='paid'&&segments.some(s=>s.differs)&&!segments.every(s=>s.text==='不限量')?'至多可享受 ':'')+text;
})}
