function animateIncomingRecord(disc){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const sleeve=disc.closest('.record-sleeve');sleeve.querySelectorAll('.incoming-record').forEach(el=>el.remove());
 const overlay=disc.cloneNode(true),rotation=getComputedStyle(disc).transform;
 overlay.classList.remove('spinning');overlay.classList.add('incoming-record');
 overlay.removeAttribute('role');overlay.removeAttribute('tabindex');overlay.removeAttribute('title');overlay.setAttribute('aria-hidden','true');
 overlay.querySelectorAll('[tabindex],[role]').forEach(el=>{el.removeAttribute('tabindex');el.removeAttribute('role')});
 sleeve.append(overlay);
 disc.classList.add("record-switching");
 const base='translate(-50%,-50%)';
 const width=disc.offsetWidth,side=-width*.78;
 const rotationPart=rotation==='none'?'':rotation;
 const out=base+' translate('+side+'px,-18px) rotate(-12deg) '+rotationPart;
 const animation=overlay.animate([{transform:base+' '+rotationPart},{transform:out}],{duration:1000,easing:'cubic-bezier(.3,0,.2,1)',fill:'forwards'});
 animation.onfinish=()=>{overlay.style.zIndex='0';const back=overlay.animate([{transform:out},{transform:base+' translate(12px,12px) '+rotationPart}],{duration:1200,easing:'cubic-bezier(.25,.1,.25,1)',fill:'forwards'});back.onfinish=()=>{overlay.remove();disc.classList.remove("record-switching")}};
}
