// A shared icon for dialog dismiss controls, independent of the chosen text font.
(() => {
 const candidates='button[aria-label^="关闭"],button[data-member-close],button[data-detail-close],button.close,.dialog-heading>button[data-action="close"],[class*="-heading"]>button';
 function normalize(root){
  if(root.nodeType===1&&!root.closest('dialog')&&!root.querySelector('dialog'))return;
  const buttons=[...(root.matches?.(candidates)?[root]:[]),...root.querySelectorAll(candidates)];
  for(const button of buttons){
   if(!button.closest('dialog')||button.matches('.corner-close-entry')||button.querySelector('[data-dialog-close-icon]'))continue;
   const label=button.getAttribute('aria-label')||'',text=button.textContent.trim();
   if(!label.startsWith('关闭')&&!['×','✕'].includes(text))continue;
   button.classList.add('dialog-close-control');
   if(!label)button.setAttribute('aria-label','关闭');
   button.innerHTML='<svg data-dialog-close-icon viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg>';
  }
 }
 normalize(document);
 new MutationObserver(records=>{for(const record of records){if(record.target.matches?.(candidates))normalize(record.target);for(const node of record.addedNodes)if(node.nodeType===1)normalize(node);}}).observe(document.body,{childList:true,subtree:true});
})();

// Profile center states and separate account-security editors.
(()=>{
 const dialog=(id,title)=>{let d=$('#'+id);if(!d){d=document.createElement('dialog');d.id=id;document.body.append(d)}d.innerHTML='<div class="dialog-heading"><h2>'+title+'</h2><button data-local-close aria-label="关闭'+title+'">×</button></div>';d.querySelector('[data-local-close]').onclick=()=>d.close();return d};
 const saveProfile=(d)=>{const profile=accountProfile(),nickname=d.querySelector('[data-profile-nickname],#profile-name')?.value.trim();prefs.accountProfile={...profile,name:nickname||profile.name||'一隅拾光',profileCompleted:true};accountOnboarding=false;persist();d.close();window.ShiyuWorld?.close();view='home';render();window.scrollTo({top:0,behavior:'instant'});toast('个人资料已保存')};
 const openProfileEditor=(kind)=>{const profile=accountProfile(),d=dialog('profile-item-editor',kind==='avatar'?'修改头像':kind==='gender'?'修改性别':kind==='realName'?'修改姓名':'修改昵称');let body='';if(kind==='avatar'){const avatars=typeof genderProfileAvatars==='function'?genderProfileAvatars(profile):ACCOUNT_AVATARS;body='<div class="profile-editor-options">'+avatars.map(id=>'<button type="button" data-profile-choice="'+esc(id)+'" aria-pressed="'+String(profile.avatar===id)+'">'+entityIcon(id)+'<small>'+esc(ENTITY_ICONS[id]?.[0]||'头像')+'</small></button>').join('')+'</div>'}else if(kind==='gender'){body='<div class="profile-editor-options profile-gender-options">'+[['male','男'],['female','女'],['private','暂不透露']].map(([id,label])=>'<button type="button" data-profile-choice="'+id+'" aria-pressed="'+String((profile.gender||'private')===id)+'">'+label+'</button>').join('')+'</div>'}else body='<input data-profile-item-value maxlength="24" value="'+esc(kind==='realName'?(profile.realName||''):(profile.name||''))+'" placeholder="请输入'+(kind==='realName'?'姓名':'昵称')+'"><button class="primary full" data-profile-item-save>保存</button>';d.insertAdjacentHTML('beforeend',body);if(kind==='avatar'||kind==='gender')d.querySelectorAll('[data-profile-choice]').forEach(button=>button.onclick=()=>{prefs.accountProfile={...accountProfile(),...(kind==='avatar'?{avatar:button.dataset.profileChoice}:{gender:button.dataset.profileChoice})};persist();d.close();openAccountCenter()});d.querySelector('[data-profile-item-save]')?.addEventListener('click',()=>{const value=d.querySelector('[data-profile-item-value]').value.trim();if(!value){toast('请输入内容');return}prefs.accountProfile={...accountProfile(),...(kind==='realName'?{realName:value}:{name:value})};persist();d.close();openAccountCenter()});if(!d.open)d.showModal()};
 const securityEditor=(kind)=>{const profile=accountProfile(),d=dialog('account-security-editor',kind==='password'?'修改密码':kind==='phone'?'修改手机号':kind==='email'?'修改邮箱':'微信绑定');let body='';if(kind==='password')body='<p class="account-note">修改后，下次登录需要使用新密码。</p><div class="security-form"><input data-security-current type="password" placeholder="当前密码"><input data-security-new type="password" placeholder="新密码（8–64 位，至少两类字符）"><input data-security-confirm type="password" placeholder="确认新密码"><button class="primary" data-security-editor-save>保存新密码</button></div>';if(kind==='phone')body='<p class="account-note">当前手机号：'+esc(profile.phone||'未绑定')+'</p><div class="security-form"><input data-security-phone inputmode="tel" placeholder="新手机号"><div class="account-input-row"><input data-security-phone-code inputmode="numeric" maxlength="8" placeholder="短信验证码"><button data-security-phone-send disabled>获取验证码</button></div><button class="primary" data-security-editor-save>保存手机号</button></div>';if(kind==='email')body='<p class="account-note">当前邮箱：'+esc(profile.email||'未绑定')+'</p><div class="security-form"><input data-security-email type="email" autocomplete="email" placeholder="新邮箱地址"><div class="account-input-row"><input data-security-email-code inputmode="numeric" maxlength="8" placeholder="邮箱验证码"><button data-security-email-send disabled>获取验证码</button></div><button class="primary" data-security-editor-save>保存邮箱</button></div>';if(kind==='wechat')body='<p class="account-note">当前状态：'+esc(profile.wechatNickname?'已绑定 · '+profile.wechatNickname:'未绑定')+'</p><div class="wechat-qr-placeholder" aria-label="微信绑定二维码"><span>微信服务号接入后显示二维码</span></div><p class="account-note">绑定微信需要扫码并等待服务号返回确认结果。</p>';d.insertAdjacentHTML('beforeend',body);if(kind==='password')d.querySelector('[data-security-editor-save]').onclick=async()=>{const current=d.querySelector('[data-security-current]').value,next=d.querySelector('[data-security-new]').value,confirm=d.querySelector('[data-security-confirm]').value;if(!current||!next){toast('请完整填写密码');return}if(next!==confirm){toast('两次输入的新密码不一致');return}try{await fetch('/api/shiyu/auth/security',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'password',currentPassword:current,newPassword:next})}).then(async response=>{const value=await response.json();if(!response.ok)throw new Error(value.message||'密码修改失败')});d.close();toast('密码修改成功')}catch(error){toast(error.message||'密码修改失败')}};if(kind==='phone'){const phone=d.querySelector('[data-security-phone]'),send=d.querySelector('[data-security-phone-send]'),code=d.querySelector('[data-security-phone-code]');const sync=()=>{const ready=/^1\d{10}$/.test(phone.value.trim());send.disabled=!ready;send.classList.toggle('is-ready',ready)};phone.oninput=sync;send.onclick=async()=>{try{const response=await fetch('/api/shiyu/auth/send-code',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone:phone.value.trim(),purpose:'change-phone'})});const value=await response.json();if(!response.ok)throw new Error(value.message||'验证码发送失败');toast('验证码已发送，'+Math.round(Number(value.expiresIn||600)/60)+'分钟内有效');send.disabled=true}catch(error){toast(error.message||'验证码发送失败')}};d.querySelector('[data-security-editor-save]').onclick=async()=>{try{const response=await fetch('/api/shiyu/auth/security',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'phone',phone:phone.value.trim(),code:code.value.trim()})});const value=await response.json();if(!response.ok)throw new Error(value.message||'手机号修改失败');prefs.accountProfile={...accountProfile(),phone:phone.value.trim()};persist();d.close();openAccountCenter();toast('手机号修改成功')}catch(error){toast(error.message||'手机号修改失败')}};sync()}if(kind==='email'){const email=d.querySelector('[data-security-email]'),send=d.querySelector('[data-security-email-send]'),code=d.querySelector('[data-security-email-code]'),valid=value=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);const sync=()=>{const ready=valid(email.value.trim());send.disabled=!ready;send.classList.toggle('is-ready',ready)};email.oninput=sync;send.onclick=async()=>{const value=email.value.trim().toLowerCase();if(!valid(value)){toast('请输入正确的邮箱地址');return}send.disabled=true;try{const response=await fetch('/api/shiyu/auth/email/send',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:value,purpose:'change-email'})});const result=await response.json();if(!response.ok)throw new Error(result.message||'验证码发送失败');toast('验证码已发送，'+Math.round(Number(result.expiresIn||600)/60)+'分钟内有效');}catch(error){send.disabled=false;toast(error.message||'验证码发送失败')}};d.querySelector('[data-security-editor-save]').onclick=async()=>{const value=email.value.trim().toLowerCase(),credential=code.value.trim();if(!valid(value)){toast('请输入正确的邮箱地址');return}if(!credential){toast('请输入邮箱验证码');return}try{const response=await fetch('/api/shiyu/auth/security',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'email',email:value,code:credential})});const result=await response.json();if(!response.ok)throw new Error(result.message||'邮箱修改失败');prefs.accountProfile={...accountProfile(),email:value};persist();d.close();openAccountCenter();toast('邮箱修改成功')}catch(error){toast(error.message||'邮箱修改失败')}};sync()}if(!d.open)d.showModal()};
 window.openShiyuSecuritySettings=()=>{const profile=accountProfile(),d=dialog('account-security','账号与安全');d.insertAdjacentHTML('beforeend','<div class="security-overview"><button data-security-item="wechat"><b>微信</b><small>'+(profile.wechatNickname?'已绑定 · '+esc(profile.wechatNickname):'未绑定')+'</small></button><button data-security-item="password"><b>修改密码</b><small>更新登录密码</small></button><button data-security-item="phone"><b>手机号</b><small>'+esc(profile.phone||'未绑定')+'</small></button><button data-security-item="email"><b>邮箱</b><small>'+esc(profile.email||'未绑定')+'</small></button></div>');d.querySelectorAll('[data-security-item]').forEach(button=>button.onclick=()=>securityEditor(button.dataset.securityItem));if(!d.open)d.showModal()};
 const previousCenter=openAccountCenter;openAccountCenter=function(){previousCenter();if(!signed)return;const d=$('#account-center'),profile=accountProfile(),first=!profileBasicsComplete(profile);if(!d)return;if(first){const save=[...d.querySelectorAll('button')].find(button=>/保存|开启我的拾隅/.test(button.textContent.trim()));if(save){save.textContent='保存资料';save.removeAttribute('data-onboard-finish');save.onclick=()=>saveProfile(d)}return}d.innerHTML='<div class="dialog-heading"><h2>个人中心</h2><button data-local-close aria-label="关闭个人中心">×</button></div><div class="profile-view-summary"><span class="account-avatar">'+avatarMarkup(profile.avatar)+'</span><div><b>'+esc(profile.realName||profile.name||'我')+'</b><small>'+esc(profile.phone||'已登录')+'</small></div></div><div class="profile-view-list"><button data-profile-edit="avatar"><b>头像</b><span>'+avatarMarkup(profile.avatar)+'</span></button><button data-profile-edit="realName"><b>姓名</b><span>'+esc(profile.realName||'未设置')+'</span></button><button data-profile-edit="nickname"><b>昵称</b><span>'+esc(profile.name||'未设置')+'</span></button><button data-profile-edit="gender"><b>性别</b><span>'+esc(({male:'男',female:'女',private:'暂不透露'})[profile.gender||'private'])+'</span></button><button data-profile-security><b>账号与安全</b><span>手机号、邮箱、微信与密码</span></button></div><button class="account-signout" data-account-signout>退出登录</button>';d.querySelector('[data-local-close]').onclick=()=>d.close();d.querySelectorAll('[data-profile-edit]').forEach(button=>button.onclick=()=>openProfileEditor(button.dataset.profileEdit));d.querySelector('[data-profile-security]').onclick=window.openShiyuSecuritySettings};
 window.openShiyuProfileEditor=openProfileEditor;
 window.openShiyuSecurityEditor=securityEditor;
 window.renderShiyuProfileCenter=()=>{const d=$('#account-center'),profile=accountProfile();if(!d||!signed)return;const first=!profileBasicsComplete(profile);if(first){const save=[...d.querySelectorAll('button')].find(button=>/保存资料|保存|开启我的拾隅/.test(button.textContent.trim()));if(save){save.textContent='保存资料';save.removeAttribute('data-onboard-finish');save.onclick=()=>saveProfile(d)}return}d.innerHTML='<div class="dialog-heading"><h2>个人中心</h2><button data-local-close aria-label="关闭个人中心">×</button></div><div class="profile-view-summary"><span class="account-avatar">'+avatarMarkup(profile.avatar)+'</span><div><b>'+esc(profile.realName||profile.name||'我')+'</b><small>'+esc(profile.phone||'已登录')+'</small></div></div><div class="profile-view-list"><button data-profile-edit="avatar"><b>头像</b><span>'+avatarMarkup(profile.avatar)+'</span></button><button data-profile-edit="realName"><b>姓名</b><span>'+esc(profile.realName||'未设置')+'</span></button><button data-profile-edit="nickname"><b>昵称</b><span>'+esc(profile.name||'未设置')+'</span></button><button data-profile-edit="gender"><b>性别</b><span>'+esc(({male:'男',female:'女',private:'暂不透露'})[profile.gender||'private'])+'</span></button><button data-profile-security><b>账号与安全</b><span>手机号、邮箱、微信与密码</span></button></div><button class="account-signout" data-account-signout>退出登录</button>';d.querySelector('[data-local-close]').onclick=()=>d.close();d.querySelectorAll('[data-profile-edit]').forEach(button=>button.onclick=()=>openProfileEditor(button.dataset.profileEdit));d.querySelector('[data-profile-security]').onclick=window.openShiyuSecuritySettings};
})();

// Birthday picker: a fixed middle window drives the current value while the
// year, month, and day rows scroll behind it.
(()=>{
 const previousCenter=openAccountCenter;
 function openBirthday(trigger){
  let d=$('#birthday-dialog');if(!d){d=document.createElement('dialog');d.id='birthday-dialog';document.body.append(d)}
  const now=new Date(),saved=(accountProfile().birthday||'1995-01-01').split('-').map(Number);
  const parts=[Math.min(now.getFullYear(),Math.max(1900,saved[0]||1995)),Math.min(12,Math.max(1,saved[1]||1)),saved[2]||1];
  const dayCount=()=>new Date(parts[0],parts[1],0).getDate();parts[2]=Math.min(dayCount(),Math.max(1,parts[2]));
  d.innerHTML='<div class="dialog-heading"><h2>选择生日</h2><button data-action="close" aria-label="关闭生日选择">×</button></div><div class="birth-column-labels"><span>年</span><span>月</span><span>日</span></div><div class="birth-columns">'+['年','月','日'].map(label=>'<div class="birth-wheel"><div class="birth-column" role="listbox" aria-label="'+label+'"></div><span class="birth-selection" aria-hidden="true"></span></div>').join('')+'</div><div class="birth-footer"><button data-birthday-save>确认生日</button></div>';
  const columns=[...d.querySelectorAll('.birth-column')],frames=[0,0,0];
  const paint=index=>columns[index].querySelectorAll('[data-birthday-column]').forEach(button=>{const selected=Number(button.dataset.value)===parts[index];button.classList.toggle('birth-center',selected);button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});
  const center=(column,button)=>{const box=column.getBoundingClientRect(),item=button.getBoundingClientRect();column.scrollTo({top:column.scrollTop+item.top+item.height/2-box.top-column.clientHeight/2,behavior:'instant'})};
  const drawColumn=index=>{const count=index===0?now.getFullYear()-1899:index===1?12:dayCount(),first=index===0?1900:1;columns[index].innerHTML=Array.from({length:count},(_,i)=>{const value=first+i;return '<button type="button" role="option" data-birthday-column="'+index+'" data-value="'+value+'">'+value+'</button>'}).join('');paint(index);center(columns[index],columns[index].querySelector('[aria-selected="true"]'))};
  const select=(index,value)=>{const previousCount=dayCount();parts[index]=value;paint(index);if(index<2&&previousCount!==dayCount()){parts[2]=Math.min(parts[2],dayCount());drawColumn(2)}};
  const sync=index=>{const column=columns[index],middle=column.getBoundingClientRect().top+column.clientHeight/2;let nearest=null,distance=Infinity;for(const button of column.children){const box=button.getBoundingClientRect(),delta=Math.abs(box.top+box.height/2-middle);if(delta<distance){nearest=button;distance=delta}}if(nearest)select(index,Number(nearest.dataset.value))};
  d.onclick=event=>{const button=event.target.closest('button');if(!button)return;if(button.hasAttribute('data-birthday-column')){const index=Number(button.dataset.birthdayColumn);select(index,Number(button.dataset.value));center(columns[index],button);return}if(button.hasAttribute('data-birthday-save')){[0,1,2].forEach(sync);const value=parts.map((part,index)=>index?String(part).padStart(2,'0'):part).join('-');if(new Date(value+'T00:00:00')>now){toast('生日不能晚于今天');return}prefs.accountProfile={...accountProfile(),birthday:value};persist();d.close();openAccountCenter()}};
  d.onclose=()=>{frames.forEach(cancelAnimationFrame);trigger?.setAttribute('aria-expanded','false');if(trigger?.isConnected)trigger.focus()};
  trigger?.setAttribute('aria-expanded','true');if(!d.open)d.showModal();[0,1,2].forEach(drawColumn);
  columns.forEach((column,index)=>{column.addEventListener('scroll',()=>{cancelAnimationFrame(frames[index]);frames[index]=requestAnimationFrame(()=>sync(index))},{passive:true});column.addEventListener('keydown',event=>{let value=parts[index];if(event.key==='ArrowDown')value++;else if(event.key==='ArrowUp')value--;else if(event.key==='Home')value=Number(column.firstElementChild.dataset.value);else if(event.key==='End')value=Number(column.lastElementChild.dataset.value);else return;const target=column.querySelector('[data-value="'+value+'"]');event.preventDefault();if(target){select(index,value);center(column,target);target.focus({preventScroll:true})}})});
 }
 window.openShiyuBirthday=openBirthday;
 openAccountCenter=function(){previousCenter();if(!signed)return;const trigger=$('#account-center .birthday-trigger');if(!trigger)return;trigger.onclick=()=>openBirthday(trigger)};
})();

// Search picker: keep the existing native value and submission flow, while
// presenting the grouped engines as searchable horizontal tabs.
(()=>{
 const logos={google:'google',baidu:'baidu',bing:'bing', 'google-images':'google','baidu-images':'baidu','bing-images':'bing','sogou-images':'sogou',huaban:'huaban',zcool:'zcool',pinterest:'pinterest',unsplash:'unsplash',pexels:'pexels'};
 function decorate(list){
  if(!list||list.querySelector('.search-engine-tabs-nav'))return;
  const groups=[...list.querySelectorAll('.search-engine-group')];if(!groups.length)return;
  const slug=id=>logos[id]||'search';
  list.classList.add('search-engine-tabs-list');
  list.innerHTML=`<div class="search-engine-tabs-nav" role="tablist">${groups.map((group,i)=>`<button type="button" role="tab" aria-selected="${i===0}" data-engine-tab="${i}">${group.querySelector('.search-engine-heading')?.textContent||'搜索'}</button>`).join('')}</div><div class="search-engine-tab-panels">${groups.map((group,i)=>`<section class="search-engine-tab-panel" role="tabpanel" data-engine-panel="${i}" ${i?'hidden':''}><label class="search-engine-filter"><span aria-hidden="true">⌕</span><input type="search" placeholder="搜索${group.querySelector('.search-engine-heading')?.textContent||'引擎'}" aria-label="搜索${group.querySelector('.search-engine-heading')?.textContent||'引擎'}"></label><div class="search-engine-options">${[...group.querySelectorAll('button[data-value]')].map(button=>{const id=button.dataset.value,label=button.firstChild?.textContent?.trim()||button.textContent.trim();return `<button type="button" role="option" aria-selected="${button.getAttribute('aria-selected')==='true'}" data-value="${esc(id)}"><img class="search-engine-logo" src="https://cdn.simpleicons.org/${slug(id)}" alt="" aria-hidden="true" onerror="this.hidden=true"><span>${esc(label)}</span>${button.getAttribute('aria-selected')==='true'?'<b aria-hidden="true">✓</b>':''}</button>`}).join('')}</div></section>`).join('')}</div>`;
  list.querySelectorAll('.search-engine-filter,.search-engine-logo').forEach(node=>node.remove());
  const preferred=typeof defaultSearchEngine==='function'?defaultSearchEngine(!!list.parentElement.querySelector('select[data-regional-search]')):'baidu';
  const primary=list.querySelector('[data-engine-panel="0"] .search-engine-options'),first=primary?.querySelector('[data-value="'+preferred+'"]');
  if(first)primary.prepend(first);
  list.querySelectorAll('[data-engine-tab]').forEach(tab=>tab.onclick=()=>{const index=tab.dataset.engineTab;list.querySelectorAll('[data-engine-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===tab)));list.querySelectorAll('[data-engine-panel]').forEach(panel=>panel.hidden=panel.dataset.enginePanel!==index)});
 }
 document.addEventListener('shiyu-engine-picker-open',event=>decorate(event.target));
 document.addEventListener('click',event=>{const trigger=event.target.closest?.('#search-form .select-trigger');if(!trigger)return;setTimeout(()=>decorate(trigger.parentElement.querySelector('.select-options')),0)},true);
})();

// Account security settings. This block is intentionally scoped to the
