  const warmWechatQr=result=>{if(result?.qrUrl){const image=new Image();image.decoding='async';image.src=result.qrUrl}};
  const cachedWechatQr=()=>{try{const value=JSON.parse(sessionStorage.getItem('shiyu-wechat-qr')||'null');if(value?.scene&&value?.qrUrl&&Number(value.expiresAt)>Date.now()+30000)return value;sessionStorage.removeItem('shiyu-wechat-qr')}catch{}return null};
