    d.dataset.preventBackdropClose='true';d.innerHTML='<div class="dialog-heading"><h2>绑定邮箱或手机号</h2><button data-wechat-close aria-label="关闭">×</button></div><p class="account-note">绑定后可以使用邮箱或手机号登录。</p><label>邮箱/手机号<input data-wechat-account autocomplete="username" placeholder="请输入邮箱或手机号"></label><label>验证码<div class="account-input-row"><input data-wechat-code inputmode="numeric" maxlength="8" placeholder="请输入验证码"><button type="button" data-wechat-code-send disabled>获取验证码</button></div></label><p class="account-status" data-wechat-status role="status"></p><button type="button" class="primary full" data-wechat-bind>绑定并登录</button><button type="button" class="wechat-skip" data-wechat-skip>暂不设置</button>';
    const account=d.querySelector('[data-wechat-account]'),send=d.querySelector('[data-wechat-code-send]'),validEmail=value=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()),validPhone=value=>/^1\d{10}$/.test(value.trim()),valid=value=>validEmail(value)||validPhone(value);
